CREATE TABLE public.platform_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,role text NOT NULL DEFAULT 'super_admin' CHECK(role IN ('super_admin')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,role));
GRANT SELECT ON public.platform_roles TO authenticated;
GRANT ALL ON public.platform_roles TO service_role;
ALTER TABLE public.platform_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own platform role" ON public.platform_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.platform_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid,action text NOT NULL,entity_id uuid,detail jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.platform_audit TO authenticated;
GRANT ALL ON public.platform_audit TO service_role;
ALTER TABLE public.platform_audit ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.can_platform(_permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _permission IN ('admin.platform','admin.users','admin.audit','admin.reference') AND EXISTS(SELECT 1 FROM public.platform_roles WHERE user_id=auth.uid() AND role='super_admin'); $$;
REVOKE ALL ON FUNCTION public.can_platform(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_platform(text) TO authenticated;
CREATE POLICY "Platform audit viewer" ON public.platform_audit FOR SELECT TO authenticated USING(public.can_platform('admin.audit'));
CREATE OR REPLACE FUNCTION public.farm360_grant_verified_platform_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.email_confirmed_at IS NOT NULL AND lower(NEW.email) IN ('jmuziransa@gmail.com','muziransa7@gmail.com','muziransaj@gmail.com') THEN INSERT INTO public.platform_roles(user_id,role) VALUES(NEW.id,'super_admin') ON CONFLICT DO NOTHING; IF FOUND THEN INSERT INTO public.platform_audit(actor_id,action,entity_id,detail) VALUES(NEW.id,'verified_super_admin_granted',NEW.id,'{"source":"verified_email"}'::jsonb); END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER farm360_verified_platform_admin AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.farm360_grant_verified_platform_admin();
CREATE OR REPLACE FUNCTION public.platform_overview() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_platform('admin.platform') THEN RAISE EXCEPTION 'Not authorized'; END IF; RETURN jsonb_build_object('users',(SELECT count(*) FROM public.profiles),'farms',(SELECT count(*) FROM public.farms WHERE NOT archived),'pending_requests',(SELECT count(*) FROM public.role_requests WHERE status='Pending')); END; $$;
REVOKE ALL ON FUNCTION public.platform_overview() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.platform_overview() TO authenticated;
CREATE POLICY "Platform reviews role requests" ON public.role_requests FOR SELECT TO authenticated USING(public.can_platform('admin.users'));
CREATE OR REPLACE FUNCTION public.reject_platform_audit_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Audit entries are immutable'; END; $$;
CREATE TRIGGER immutable_platform_audit BEFORE UPDATE OR DELETE ON public.platform_audit FOR EACH ROW EXECUTE FUNCTION public.reject_platform_audit_mutation();